import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_gelu_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_div_gelu_kernel(const float* input, float divisor, float* output, int size) {
    const int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < size) {
        float val = input[index] / divisor;
        const float sqrt_2_over_2 = 0.7071067811865475f;
        float gelu = 0.5f * val * (1.0f + erff(val * sqrt_2_over_2));
        output[index] = gelu;
    }
}

torch::Tensor fused_div_gelu_cuda(torch::Tensor input, float divisor) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    fused_div_gelu_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        divisor,
        output.data_ptr<float>(),
        size
    );

    return output;
}
"""

fused_gelu_cpp = "torch::Tensor fused_div_gelu_cuda(torch::Tensor input, float divisor);"

fused_gelu_ext = load_inline(
    name="fused_gelu",
    cpp_sources=fused_gelu_cpp,
    cuda_sources=fused_gelu_source,
    functions=["fused_div_gelu_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused_gelu = fused_gelu_ext

    def forward(self, x):
        x = self.linear(x)
        x = self.fused_gelu.fused_div_gelu_cuda(x, self.divisor)
        return x
